import { useActionState } from 'react';

async function updateName(previousState: { message: string }, formData: FormData) {
  const name = String(formData.get('name') ?? '').trim();
  if (!name) return { message: 'Enter a name.' };
  await new Promise((resolve) => setTimeout(resolve, 300));
  return { message: `Saved ${name}` };
}

export default function ProfileForm() {
  const [state, formAction, isPending] = useActionState(updateName, {
    message: '',
  });

  return (
    <form action={formAction}>
      <label>
        Name <input name="name" disabled={isPending} />
      </label>
      <button disabled={isPending}>
        {isPending ? 'Saving…' : 'Save'}
      </button>
      <p aria-live="polite">{state.message}</p>
    </form>
  );
}

