import { useOptimistic, useState } from "react";

export default function MessageForm() {
  const [messages, setMessages] = useState<string[]>([]);
  const [optimisticMessages, addOptimisticMessage] = useOptimistic(
    messages,
    (current, message: string) => [...current, message]
  );

  async function send(formData: FormData) {
    const message = String(formData.get("message"));
    addOptimisticMessage(message);
    try {
      await saveMessage(message);
      setMessages(current => [...current, message]);
    } catch {
      alert("Sending failed; the message was rolled back.");
    }
  }

  return <form action={send}>
    {optimisticMessages.map((message, i) => <div key={i}>{message}</div>)}
    <input name="message" required />
    <button>Send</button>
  </form>;
}

async function saveMessage(message: string) {
  await new Promise(resolve => setTimeout(resolve, 500));
  if (message === "fail") throw new Error("Request failed");
}

